const __SPC=(tags,ow,lex)=>{try{const IX=L2C.index(ow,lex);const VO={active:/^[AQ]$/,passive:/^[POEN]$/,middle:/^[MDEN]$/};
 for(const t of tags||[]){if(!t||t.status==='IGNORED')continue;const seg=String(t.seg||'');const R=L2C.refsIn(seg).filter(k=>(IX.V[k]||[]).length);if(!R.length)continue;const out=[];
  const SN=seg.split(/(?<=[^.][.!?;]|[!?;])["”'’)\]]*\s+(?=["“'‘(*_\[]*[A-Za-z0-9\u00C0-\u024F])/);for(const sn of SN){const NM=[...sn.matchAll(/\b([GH])0*(\d{1,5})\b/g)];NM.forEach((m,j)=>{const n=m[1]+m[2];let tail=sn.slice(m.index+m[0].length,j+1<NM.length?NM[j+1].index:sn.length);const nx=tail.search(/[*_][^\s*_]|\b(?:and|while|whereas|but)\s+[*_]/);if(nx>=0)tail=tail.slice(0,nx);const OT=k=>(IX.V[k]||[]).some(r=>/^H/.test(r.strongs_number||''));const __cue=(tl,k)=>{const mm=k.match(/^(.+) (\d+):(\d+)$/);if(!mm)return false;const re=new RegExp(mm[1].replace(/\s+/g,'\\s+')+'\\.?\\s+'+mm[2]+':'+mm[3]+'(?!\\d)','g');for(const z of tl.matchAll(re)){const pre=tl.slice(Math.max(0,z.index-60),z.index);const post=tl.slice(z.index+z[0].length,z.index+z[0].length+3);if(/^\s*[-–]\s*\d/.test(post))continue;if(/\b(?:after|before|through|than|not|question\s+of|gives?|defines?|joins?|sign\s+of)\b[^.;]*$/i.test(pre))continue;if(/\b(?:in|at|stands\s+in|word\s+(?:of|in|at)|verb\s+(?:of|in|at)|same\s+\w+\s+as|shared\s+with|as\s+in)\s*$/i.test(pre)||/\b(?:in|at)\s+[^.;()]*\d:\d+\s*(?:,|\band)\s*$/i.test(pre)&&!/,\s*and\s*$/.test(pre))return true;}return false;};const CR=L2C.refsIn(tail).filter(k=>__cue(tail,k)&&(IX.V[k]||[]).length&&(OT(k)===(m[1]==='H')));if(!CR.length)return;const hit=CR.filter(k=>IX.V[k].some(r=>L2C.numOf(r.strongs_number)===n));
   for(const k of CR){if(hit.includes(k))continue;if(NM.some((o,jj)=>jj!==j&&(IX.V[k]||[]).some(r=>L2C.numOf(r.strongs_number)===o[1]+o[2])))continue;let there='';const __bf=sn.slice(0,m.index).toLowerCase();for(const w of (t.words||[]).slice().sort((a,b)=>__bf.lastIndexOf(String(b.w).toLowerCase())-__bf.lastIndexOf(String(a.w).toLowerCase()))){if(__bf.lastIndexOf(String(w.w).toLowerCase())<0)continue;if(w.kind==='strongs')continue;const mw=L2C.matchWord({w:w.w,kind:w.kind},IX.V[k],IX);if(mw.ok&&mw.num&&mw.num!==n){there=mw.num;break;}}
    out.push(n+' is named as standing in '+k+', which does not hold it'+(there?' ('+there+' stands there for that word)':'')+(hit.length?'; it stands in '+hit.join(', '):''));}});}
  const vo=[...new Set((seg.match(/\b(active|passive|middle)\b/gi)||[]).map(x=>x.toLowerCase()))];
  if(vo.length===1&&R.length===1){const ok=(t.words||[]).filter(w=>w.ok&&w.num&&/^G/.test(w.num));if(ok.length&&new Set(ok.map(w=>w.num)).size===1){const rows=(IX.V[R[0]]||[]).filter(r=>L2C.numOf(r.strongs_number)===ok[0].num);const vs=rows.map(r=>(String(r.morph||'').match(/^V-2?[PIFARL]([AMPDONEQX])/)||[])[1]).filter(Boolean);
   if(vs.length&&!vs.some(v=>VO[vo[0]].test(v)))out.push(ok.filter(w=>w.kind!=='strongs').concat(ok)[0].w+' ('+ok[0].num+') is called '+vo[0]+'; in '+R[0]+' its form is '+rows.map(r=>String(r.morph||'').split(' ')[0]).join(', '));}}
  if(out.length)t.place=out.slice(0,4);}}catch(e){}return tags;};
